it("AC-001-01 adds an item to an empty list", () => {
  const store = emptyStore();
  run(["add", "milk"], store);
  expect(store.items()).toEqual(["milk"]);
});

it("AC-002-03 rejects a 201-character title", async () => {
  const res = await createTask({ title: "x".repeat(201) });
  expect(res.ok).toBe(false);
  expect(res.error).toBe("Title too long");
});

it("AC-001-01 add works", () => {
  const store = emptyStore();
  run(["add", "milk"], store);
});

it("AC-002-03 creates a task", async () => {
  const res = await createTask({ title: "Buy milk" });
  expect(res.ok).toBe(true);
});
